//go:build darwin && arm64

package emitter

import (
	"bytes"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
)

// boundaryStubs are the shim stubs testdata/boundary/guest.s calls, generated by the emitter.
var boundaryStubs = [][2]string{
	{"_stub_sceFiberRun", "shim_sceFiberRun"},
	{"_stub_sceFiberSwitch", "shim_sceFiberSwitch"},
	{"_stub_sceFiberReturnToThread", "shim_sceFiberReturnToThread"},
	{"_stub_test_noop", "shim_test_noop"},
	{"_stub_test_wait_signal", "shim_test_wait_signal"},
	{"_stub_test_set_gprs", "shim_test_set_gprs"},
	{"_stub_test_xmm", "shim_test_xmm"},
}

// boundaryRuntimeSources are the runtime files the boundary tests run against.
var boundaryRuntimeSources = []string{
	"core/recomp_runtime.c",
	"kernel/threading/ps4_threading.c",
	"kernel/threading/ps4_stall_profile.c",
	"modules/libSceFiber/ps4_fiber.c",
	"modules/libkernel/ps4_kernel_sys.c",
}

// buildBoundaryHarness links the emitted trampoline and shim stubs with guest.s, harness.c
// and the runtime sources into one host program.
func buildBoundaryHarness(t *testing.T) string {
	t.Helper()
	if _, err := exec.LookPath("clang"); err != nil {
		t.Skip("clang not found")
	}
	dir := t.TempDir()
	tramp := filepath.Join(dir, "trampoline_arm64.s")
	if err := (&AsmEmitter{}).EmitTrampoline(tramp); err != nil {
		t.Fatal(err)
	}
	var stubs bytes.Buffer
	stubs.WriteString(guestTextSection + "\n.p2align 2\n\n")
	for _, s := range boundaryStubs {
		writeShimStub(&stubs, s[0], s[1])
	}
	stubPath := filepath.Join(dir, "stubs_gen.s")
	if err := os.WriteFile(stubPath, stubs.Bytes(), 0o644); err != nil {
		t.Fatal(err)
	}

	rt, err := filepath.Abs("../runtime")
	if err != nil {
		t.Fatal(err)
	}
	args := []string{"-target", "arm64-apple-darwin", "-mcpu=apple-m1", "-DRECOMP_ARM64_ASM=1", "-O1",
		"-ffp-contract=off", "-Wno-format", "-Wno-parentheses-equality"}
	err = filepath.WalkDir(rt, func(p string, d os.DirEntry, err error) error {
		if err == nil && d.IsDir() {
			args = append(args, "-I"+p)
		}
		return err
	})
	if err != nil {
		t.Fatal(err)
	}
	td, _ := filepath.Abs("testdata/boundary")
	args = append(args, filepath.Join(td, "harness.c"), filepath.Join(td, "stubs.c"), filepath.Join(td, "guest.s"),
		tramp, stubPath)
	for _, s := range boundaryRuntimeSources {
		args = append(args, filepath.Join(rt, s))
	}
	bin := filepath.Join(dir, "boundary_harness")
	args = append(args, "-o", bin)
	if out, err := exec.Command("clang", args...).CombinedOutput(); err != nil {
		t.Fatalf("building the boundary harness: %v\n%s", err, out)
	}
	return bin
}

// TestGuestStateBoundary runs the guest-state boundary cases of testdata/boundary/harness.c:
// guest code calls shims through the emitted bridge, and fibers switch inside shims.
func TestGuestStateBoundary(t *testing.T) {
	bin := buildBoundaryHarness(t)
	cases := []struct {
		name, arg string
		env       []string
	}{
		{"fiber/coroutines", "fiber", nil},
		{"fiber/threads", "fiber", []string{"PS4_FIBER_THREADS=1"}},
		{"exception-handler-in-shim", "exception", nil},
		{"shim-sets-gprs", "gprs", nil},
		{"xmm-arguments-and-results", "xmm", nil},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			cmd := exec.Command(bin, c.arg)
			cmd.Env = append(os.Environ(), c.env...)
			out, err := cmd.CombinedOutput()
			if err != nil || !strings.Contains(string(out), "PASS "+c.arg) {
				t.Fatalf("%s: %v\n%s", c.arg, err, out)
			}
		})
	}
}
